for (const item of $input.all()) {
  const score = Number(item.json.lead_score);

  if (score <= 1) {
    item.json.lead_type = "low value";
  } else if (score === 2) {
    item.json.lead_type = "medium value";
  } else if (score === 3) {
    item.json.lead_type = "high value";
  } else {
    item.json.lead_type = "unknown";
  }
}

return $input.all();
